// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IInvoiceRegistry {
    enum InvoiceStatus {
        None,
        PendingConfirmation,
        Rejected,
        Confirmed,
        FinancingOpen,
        Funded,
        Repaid,
        Overdue,
        RepaymentDeposited,
        Defaulted
    }

    struct InvoiceView {
        uint256 id;
        address supplier;
        address buyer;
        bytes32 invoiceNumberHash;
        uint256 faceValue;
        uint64 issuedAt;
        uint64 dueAt;
        bytes32 documentHash;
        InvoiceStatus status;
    }

    function getInvoice(uint256 invoiceId) external view returns (InvoiceView memory);
    function markFinancingOpen(uint256 invoiceId) external;
    function restoreConfirmed(uint256 invoiceId) external;
    function markFunded(uint256 invoiceId) external;
    function markOverdue(uint256 invoiceId) external;
    function markRepaymentDeposited(uint256 invoiceId) external;
    function markRepaid(uint256 invoiceId) external;
    function markDefaulted(uint256 invoiceId) external;
}

interfaces/IFinancingMarket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IFinancingMarket {
    enum FinancingStatus {
        None,
        Open,
        OfferAccepted,
        Funded,
        Settled,
        Cancelled,
        Expired,
        Overdue,
        Defaulted
    }

    enum OfferStatus {
        None,
        Active,
        Accepted,
        Expired
    }

    struct FinancingView {
        uint256 id;
        uint256 invoiceId;
        address supplier;
        uint256 principal;
        uint16 maxRateBps;
        uint16 holdbackBps;
        uint64 deadline;
        uint64 acceptedAt;
        uint256 acceptedOfferId;
        FinancingStatus status;
    }

    struct OfferView {
        uint256 id;
        uint256 financingId;
        address funder;
        uint16 rateBps;
        OfferStatus status;
    }

    function getFinancing(uint256 financingId) external view returns (FinancingView memory);
    function getOffer(uint256 offerId) external view returns (OfferView memory);
    function financingIdByInvoice(uint256 invoiceId) external view returns (uint256);
    function isFunderParticipant(uint256 invoiceId, address account) external view returns (bool);
    function markFunded(uint256 financingId) external;
    function markOverdue(uint256 financingId) external;
    function markSettled(uint256 financingId) external;
    function markDefaulted(uint256 financingId) external;
    function cancelByDispute(uint256 invoiceId) external;
}

